UPDATE KEPRQDT /*updateKeprqdtAddImage*/
   SET IMGFILE_DIR = #{st_imgfile_dir}
   , IMGFILE_NAME = #{st_imgfile_name}
 WHERE BUYER = #{st_buyer_code} 
 AND QUOTATION_NO = #{st_quotation_no}
 AND QUOTATION_SEQ = #{st_quotation_seq}
 AND REVISION = #{st_revision}


		/* updateMasterMpRqCmsRecvDate */
			UPDATE KEPRQDT A 
				SET   CMS_RECV_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
				, CMS_RECV_TIME = TO_CHAR(SYSDATE,'HH24MISS')
				, CMS_USER_ID= #{USER_ID}
				, ITEM_CLEANSING_USER_ID = DECODE(A.ITEM_CLEANSING_USER_ID, NULL, #{USER_ID}, A.ITEM_CLEANSING_USER_ID)
				, ITEM_CLEANSING_DATE = DECODE(A.ITEM_CLEANSING_DATE, NULL, SYSDATE, A.ITEM_CLEANSING_DATE)

				, DESCRIPTION = #{st_description}
				, SPECIFICATION = #{st_specification}
                , UNIT_MEASURE = #{st_unit_measure}
                , MAKER_CODE = #{st_maker_code}
                , MAKER_NAME = #{st_maker_name}
                , ORIGIN_CODE = #{st_origin_code}
                , ORIGIN_NAME = #{st_origin_name}
                , CMS_CATEG_ID = #{st_cms_categ_id}
			    , ITEM_DETAIL_DESC = #{st_item_detail_desc}
			    , DESCRIPTION_ENG = #{st_description_eng}
				, SPECIFICATION_ENG = #{st_specification_eng}
				, IMGFILE_DIR = #{st_imgfile_dir}
				, IMGFILE_NAME = #{st_imgfile_name}
				, ATTB1_NM = #{st_attb1_nm} 
				, ATTB2_NM = #{st_attb2_nm} 
				, ATTB3_NM = #{st_attb3_nm} 
				, ATTB4_NM = #{st_attb4_nm} 
				, ATTB5_NM = #{st_attb5_nm} 
				, ATTB6_NM = #{st_attb6_nm} 
				, ATTB7_NM = #{st_attb7_nm} 
				, ATTB8_NM = #{st_attb8_nm} 
				, ATTB9_NM = #{st_attb9_nm} 
				, ATTB10_NM = #{st_attb10_nm} 
				, ATTB11_NM = #{st_attb11_nm} 
				, ATTB12_NM = #{st_attb12_nm} 
				, ATTB13_NM = #{st_attb13_nm} 
				, ATTB14_NM = #{st_attb14_nm} 
				, ATTB15_NM = #{st_attb15_nm} 
				, ATTB16_NM = #{st_attb16_nm} 
				, ATTB17_NM = #{st_attb17_nm} 
				, ATTB18_NM = #{st_attb18_nm}
